#include "common/embedded_resources.h"

// The table is generated by the build (cmake/EmbedResources.cmake, libretro/embed.sh).
extern "C" {
struct EmbeddedResource {
    const char* path;
    const unsigned char* data;
    unsigned long size;
};
extern const struct EmbeddedResource g_embedded_resources[];
extern const unsigned long g_embedded_resource_count;
}

namespace Common {

std::span<const u8> GetEmbeddedResource(std::string_view path) {
    for (unsigned long i = 0; i < g_embedded_resource_count; i++) {
        const EmbeddedResource& resource = g_embedded_resources[i];
        if (path == resource.path) {
            return {resource.data, resource.size};
        }
    }
    return {};
}

} // namespace Common
